'use client';

import React from 'react';
import { motion } from 'framer-motion';
import clsx from 'clsx';
import { parseTrainRunningDays, RunningDayItem } from '../../utils/trainRunningDays';
import { Calendar } from 'lucide-react';

interface TrainRunningDaysProps {
  runningDays?: any;
  searchDate?: string | null;
  className?: string;
  compact?: boolean;
}

export const TrainRunningDays: React.FC<TrainRunningDaysProps> = ({
  runningDays,
  searchDate,
  className = '',
  compact = false,
}) => {
  const parsed = parseTrainRunningDays(runningDays, searchDate);

  return (
    <div
      className={clsx(
        "inline-flex items-center gap-1.5 px-2.5 py-1 rounded-xl bg-input/40 dark:bg-slate-900/40 border border-subtle h-[36px] min-h-[36px] transition-all select-none shadow-xs",
        className
      )}
      title={`Runs: ${parsed.summaryText}`}
    >
      {/* Icon & Label */}
      <div className="flex items-center gap-1 text-[10px] font-bold text-secondary uppercase tracking-wider shrink-0">
        <Calendar className="w-3.5 h-3.5 text-primary shrink-0" />
        <span className="hidden xs:inline">Runs:</span>
      </div>

      {/* Days of Week: M T W T F S S */}
      <div className="flex items-center gap-0.5 sm:gap-1 shrink-0">
        {parsed.days.map((day: RunningDayItem, idx: number) => {
          const isSearched = day.isSearchedDay;
          const runs = day.runs;

          return (
            <motion.div
              key={day.key}
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              transition={{ delay: idx * 0.02, duration: 0.15 }}
              whileHover={{ scale: 1.15 }}
              className={clsx(
                "relative w-4 h-4 rounded-[4px] flex items-center justify-center font-mono text-[9px] transition-all cursor-default",
                runs
                  ? day.isSunday
                    ? "bg-rose-500/15 text-rose-600 dark:text-rose-400 border border-rose-500/35 font-black"
                    : "bg-emerald-500/15 text-emerald-700 dark:text-emerald-300 border border-emerald-500/35 font-black"
                  : "bg-slate-100 dark:bg-slate-800/40 text-slate-400 dark:text-slate-600 border border-slate-200/50 dark:border-slate-800/60 font-medium opacity-40 line-through",
                isSearched && runs && "ring-1.5 ring-blue-500 ring-offset-1 dark:ring-offset-slate-900 shadow-[0_0_8px_rgba(59,130,246,0.7)] font-black scale-105 z-10",
                isSearched && !runs && "ring-1.5 ring-amber-500/70 border-amber-500/50 scale-105 z-10"
              )}
              title={`${day.fullLabel} (${day.hindiLabel}): ${runs ? 'Runs' : 'Does NOT run'}${isSearched ? ' [Your Searched Date]' : ''}`}
            >
              <span className={clsx("leading-none", day.isSunday && "text-rose-500 dark:text-rose-400")}>
                {day.shortLabel}
              </span>

              {/* Glowing Ping on Searched Day */}
              {isSearched && (
                <span
                  className={clsx(
                    "absolute -top-0.5 -right-0.5 w-1.5 h-1.5 rounded-full border border-white dark:border-slate-900",
                    runs ? "bg-blue-500 animate-ping" : "bg-amber-500"
                  )}
                />
              )}
            </motion.div>
          );
        })}
      </div>

      {/* Mini Schedule Badge: Daily or 2d */}
      <span
        className={clsx(
          "text-[9px] font-black px-1.5 py-0.5 rounded-md tracking-tight uppercase border tabular-nums shrink-0 shadow-2xs",
          parsed.isDaily
            ? "bg-blue-500/10 text-blue-600 dark:text-blue-400 border-blue-500/25"
            : "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/25"
        )}
      >
        {parsed.isDaily ? "Daily" : `${parsed.activeCount}d`}
      </span>
    </div>
  );
};
